() => {
  const status = document.querySelector("#recommend-status").textContent;
  if (!status.includes("推荐更新失败，显示上次缓存。") || !status.includes("中国作家网") || !status.includes("福建省图书馆")) throw new Error(`Missing failure/cache/source status: ${status}`);
  return { cachedAfterHTTPFailure: true, status };
}

() => {
  const saved = JSON.parse(localStorage.getItem("page-between-reading-list"));
  const target = saved.find((book) => book.title === "梅西传");
  if (target.bookInfo.summary !== "这是我自己写的简介。" || target.bookInfo.fieldOrigins.summary !== "manual" || target.read !== true || target.unknown.nested[0] !== 7) throw new Error("Saved metadata or legacy values differ");
  if (target.bookInfo.catalogueLink.verification !== "verified") throw new Error("Missing adopted origin");
  if (!saved.some((book) => book.title === "屯堡" && book.read === false)) throw new Error("Recommendation not saved unread");
  return { summaryOrigin: "manual", legacyPreserved: true, addedUnread: true };
}

() => {
  const saved = JSON.parse(localStorage.getItem("page-between-reading-list"));
  const target = saved[0];
  if (target.title !== "我的梅西传" || target.read !== true || target.unknown.nested[0] !== 7 || target.bookInfo.summary !== "这是我自己写的简介。") throw new Error("Undo did not restore full object and index");
  if (target.bookInfo.catalogueLink.verification !== "needs_review" || target.bookInfo.catalogueLink.titleAtAdoption !== "梅西传") throw new Error("Rename origin state differs");
  return { completeUndo: true, originalIndex: 0, renamedOriginPreserved: true };
}

() => {
  const visible = [...document.querySelectorAll("h1,h2,h3,p,button,input,textarea,select")].filter((node) => node.getClientRects().length);
  const overflow = visible.filter((node) => { const rectangle = node.getBoundingClientRect(); return rectangle.left < -1 || rectangle.right > innerWidth + 1; }).map((node) => node.textContent.slice(0, 60));
  if (document.documentElement.scrollWidth > innerWidth + 1 || overflow.length) throw new Error(`Horizontal overflow: ${JSON.stringify(overflow)}`);
  return { width: innerWidth, scrollWidth: document.documentElement.scrollWidth, devicePixelRatio, overflow };
}

